    int findPattern(InfiniteStream* stream, vector<int>& pattern) {
        int m = pattern.size();
        const long long MOD = 2147483647;
        long long ph = 0, wh = 0, pm = 1;
        for (int b : pattern) ph = (ph * 2 + b) % MOD;
        for (int i = 0; i < m; i++) pm = pm * 2 % MOD;
        deque<int> win;
        int i = 0;
        while (true) {
            int b = stream->next();
            wh = (wh * 2 + b) % MOD;
            win.push_back(b);
            if ((int)win.size() > m) {
                wh = ((wh - (long long)win.front() * pm) % MOD + MOD) % MOD;
                win.pop_front();
            }
            if ((int)win.size() == m && wh == ph) {
                bool ok = true;
                int j = 0;
                for (int x : win) if (x != pattern[j++]) { ok = false; break; }
                if (ok) return i - m + 1;
