import java.util.*;
class Solution {
    public int findPattern(InfiniteStream stream, int[] pattern) {
        int m = pattern.length;
        long MOD = 2147483647, ph = 0, wh = 0, pm = 1;
        for (int b : pattern) ph = (ph * 2 + b) % MOD;
        for (int i = 0; i < m; i++) pm = pm * 2 % MOD;
        Deque<Integer> win = new ArrayDeque<>();
        int i = 0;
        while (true) {
            int b = stream.next();
            wh = (wh * 2 + b) % MOD;
            win.addLast(b);
            if (win.size() > m) {
                wh = ((wh - win.pollFirst() * pm) % MOD + MOD) % MOD;
            }
            if (win.size() == m && wh == ph) {
                boolean ok = true;
                int j = 0;
                for (int x : win) if (x != pattern[j++]) { ok = false; break; }
                if (ok) return i - m + 1;
            }
            i++;
        }
    }
}

